// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // sanity via public surface: balance recorded
        uint256 before = c.getBalance(actor);
        assertTrue(before == amount, "deposit recorded");

        vm.prank(actor);
        c.withdrawBalance();

        // General rule: after a successful withdrawal, the caller's recorded balance must be zero.
        assertTrue(c.getBalance(actor) == 0, "balance must be cleared after withdrawal");
    }
}
